# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check imports
if not any('import numpy as np' in line for line in lines):
    raise AssertionError('Task 1: Missing "import numpy as np"')
if not any('import pandas as pd' in line for line in lines):
    raise AssertionError('Task 1: Missing "import pandas as pd"')

# Task 3: Check DataFrame creation
if not any('sales_df' in line and 'pd.DataFrame' in line for line in lines):
    raise AssertionError('Task 3: sales_df should use pd.DataFrame()')

# Task 4: Check .head(3)
if not any('.head(3)' in line for line in lines):
    raise AssertionError('Task 4: Should use .head(3)')

# Task 5: Check Revenue column
if not any('Revenue' in line and 'Price' in line and 'Units_Sold' in line for line in lines):
    raise AssertionError('Task 5: Revenue should multiply Price and Units_Sold')

# Task 6: Check boolean mask
if not any("sales_df['Price'] > 200" in line or 'sales_df["Price"] > 200' in line for line in lines):
    raise AssertionError('Task 6: expensive_mask should use sales_df[\'Price\'] > 200')

# Task 7: Check mask applied
if not any('sales_df[expensive_mask]' in line.replace(' ', '') for line in lines):
    raise AssertionError('Task 7: Should apply mask with sales_df[expensive_mask]')

# Task 8: Check & filtering
if not any('&' in line and 'Units_Sold' in line and 'Price' in line for line in lines):
    raise AssertionError('Task 8: Should use & for combined boolean filter')

# Task 9: Check statistics (flexible - .mean()/.sum()/.max() OR np.mean/np.sum/np.max)
has_mean = any(('.mean()' in line and 'Revenue' in line) or ('np.mean' in line and 'Revenue' in line) for line in lines)
has_sum = any(('.sum()' in line and 'Revenue' in line) or ('np.sum' in line and 'Revenue' in line) for line in lines)
has_max = any(('.max()' in line and 'Revenue' in line) or ('np.max' in line and 'Revenue' in line) for line in lines)

if not has_mean:
    raise AssertionError('Task 9: Missing mean calculation on Revenue')
if not has_sum:
    raise AssertionError('Task 9: Missing sum calculation on Revenue')
if not has_max:
    raise AssertionError('Task 9: Missing max calculation on Revenue')

print('TEST_PASSED')
